29	/**
30	 * A class that allows a DataNode to communicate information about all
31	 * its peer DataNodes that appear to be slow.
32	 *
33	 * The wire representation of this structure is a list of
34	 * SlowPeerReportProto messages.
35	 */
36	@InterfaceAudience.Private
37	@InterfaceStability.Unstable
38	public final class SlowPeerReports {
39	  /**
40	   * A map from the DataNode's DataNodeUUID to its aggregate latency
41	   * as seen by the reporting node.
42	   *
43	   * The exact choice of the aggregate is opaque to the NameNode but it
44	   * should be chosen consistently by all DataNodes in the cluster.
45	   * Examples of aggregates are 90th percentile (good) and mean (not so
46	   * good).
47	   *
48	   * The NameNode must not attempt to interpret the aggregate latencies
49	   * beyond exposing them as a diagnostic. e.g. metrics. Also, comparing
50	   * latencies across reports from different DataNodes may not be not
51	   * meaningful and must be avoided.
52	   */
53	  @Nonnull
54	  private final Map<String, Double> slowPeers;
55	
56	  /**
57	   * An object representing a SlowPeerReports with no entries. Should
58	   * be used instead of null or creating new objects when there are
59	   * no slow peers to report.
60	   */
61	  public static final SlowPeerReports EMPTY_REPORT =
62	      new SlowPeerReports(ImmutableMap.of());
63	
64	  private SlowPeerReports(Map<String, Double> slowPeers) {
65	    this.slowPeers = slowPeers;
66	  }
67	
68	  public static SlowPeerReports create(
69	      @Nullable Map<String, Double> slowPeers) {
70	    if (slowPeers == null || slowPeers.isEmpty()) {
71	      return EMPTY_REPORT;
72	    }
73	    return new SlowPeerReports(slowPeers);
74	  }
75	
76	  public Map<String, Double> getSlowPeers() {
77	    return slowPeers;
78	  }
79	
80	  public boolean haveSlowPeers() {
81	    return slowPeers.size() > 0;
82	  }
83	
84	  /**
85	   * Return true if the two objects represent the same set slow peer
86	   * entries. Primarily for unit testing convenience.
87	   */
88	  @Override
89	  public boolean equals(Object o) {
90	    if (this == o) {
91	      return true;
92	    }
93	
94	    if (!(o instanceof SlowPeerReports)) {
95	      return false;
96	    }
97	
98	    SlowPeerReports that = (SlowPeerReports) o;
99	
100	    return slowPeers.equals(that.slowPeers);
101	  }
102	
103	  @Override
104	  public int hashCode() {
105	    return slowPeers.hashCode();
106	  }
107	}

