52	/**
53	 * This class aggregates information from {@link SlowPeerReports} received via
54	 * heartbeats.
55	 */
56	@InterfaceAudience.Private
57	@InterfaceStability.Unstable
58	public class SlowPeerTracker {
59	  public static final Logger LOG =
60	      LoggerFactory.getLogger(SlowPeerTracker.class);
61	
62	  /**
63	   * Time duration after which a report is considered stale. This is
64	   * set to DFS_DATANODE_OUTLIERS_REPORT_INTERVAL_KEY * 3 i.e.
65	   * maintained for at least two successive reports.
66	   */
67	  private final long reportValidityMs;
68	
69	  /**
70	   * Timer object for querying the current time. Separated out for
71	   * unit testing.
72	   */
73	  private final Timer timer;
74	
75	  /**
76	   * ObjectWriter to convert JSON reports to String.
77	   */
78	  private static final ObjectWriter WRITER = new ObjectMapper().writer();
79	  /**
80	   * Number of nodes to include in JSON report. We will return nodes with
81	   * the highest number of votes from peers.
82	   */
83	  private final int maxNodesToReport;
84	
85	  /**
86	   * Information about peers that have reported a node as being slow.
87	   * Each outer map entry is a map of (DatanodeId) {@literal ->} (timestamp),
88	   * mapping reporting nodes to the timestamp of the last report from
89	   * that node.
90	   *
91	   * DatanodeId could be the DataNodeId or its address. We
92	   * don't care as long as the caller uses it consistently.
93	   *
94	   * Stale reports are not evicted proactively and can potentially
95	   * hang around forever.
96	   */
97	  private final ConcurrentMap<String, ConcurrentMap<String, Long>>
98	      allReports;
99	
100	  public SlowPeerTracker(Configuration conf, Timer timer) {
101	    this.timer = timer;
102	    this.allReports = new ConcurrentHashMap<>();
103	    this.reportValidityMs = conf.getTimeDuration(
104	        DFSConfigKeys.DFS_DATANODE_OUTLIERS_REPORT_INTERVAL_KEY,
105	        DFSConfigKeys.DFS_DATANODE_OUTLIERS_REPORT_INTERVAL_DEFAULT,
106	        TimeUnit.MILLISECONDS) * 3;
107	    this.maxNodesToReport = conf.getInt(
108	        DFSConfigKeys.DFS_DATANODE_MAX_NODES_TO_REPORT_KEY,
109	        DFSConfigKeys.DFS_DATANODE_MAX_NODES_TO_REPORT_DEFAULT);
110	  }
111	
112	  /**
113	   * Add a new report. DatanodeIds can be the DataNodeIds or addresses
114	   * We don't care as long as the caller is consistent.
115	   *
116	   * @param reportingNode DataNodeId of the node reporting on its peer.
117	   * @param slowNode DataNodeId of the peer suspected to be slow.
118	   */
119	  public void addReport(String slowNode,
120	                        String reportingNode) {
121	    ConcurrentMap<String, Long> nodeEntries = allReports.get(slowNode);
122	
123	    if (nodeEntries == null) {
124	      // putIfAbsent guards against multiple writers.
125	      allReports.putIfAbsent(slowNode, new ConcurrentHashMap<>());
126	      nodeEntries = allReports.get(slowNode);
127	    }
128	
129	    // Replace the existing entry from this node, if any.
130	    nodeEntries.put(reportingNode, timer.monotonicNow());
131	  }
132	
133	  /**
134	   * Retrieve the non-expired reports that mark a given DataNode
135	   * as slow. Stale reports are excluded.
136	   *
137	   * @param slowNode target node Id.
138	   * @return set of reports which implicate the target node as being slow.
139	   */
140	  public Set<String> getReportsForNode(String slowNode) {
141	    final ConcurrentMap<String, Long> nodeEntries =
142	        allReports.get(slowNode);
143	
144	    if (nodeEntries == null || nodeEntries.isEmpty()) {
145	      return Collections.emptySet();
146	    }
147	
148	    return filterNodeReports(nodeEntries, timer.monotonicNow());
149	  }
150	
151	  /**
152	   * Retrieve all reports for all nodes. Stale reports are excluded.
153	   *
154	   * @return map from SlowNodeId {@literal ->} (set of nodes reporting peers).
155	   */
156	  public Map<String, SortedSet<String>> getReportsForAllDataNodes() {
157	    if (allReports.isEmpty()) {
158	      return ImmutableMap.of();
159	    }
160	
161	    final Map<String, SortedSet<String>> allNodesValidReports = new HashMap<>();
162	    final long now = timer.monotonicNow();
163	
164	    for (Map.Entry<String, ConcurrentMap<String, Long>> entry :
165	        allReports.entrySet()) {
166	      SortedSet<String> validReports = filterNodeReports(entry.getValue(), now);
167	      if (!validReports.isEmpty()) {
168	        allNodesValidReports.put(entry.getKey(), validReports);
169	      }
170	    }
171	    return allNodesValidReports;
172	  }
173	
174	  /**
175	   * Filter the given reports to return just the valid ones.
176	   *
177	   * @param reports
178	   * @param now
179	   * @return
180	   */
181	  private SortedSet<String> filterNodeReports(
182	      ConcurrentMap<String, Long> reports, long now) {
183	    final SortedSet<String> validReports = new TreeSet<>();
184	
185	    for (Map.Entry<String, Long> entry : reports.entrySet()) {
186	      if (now - entry.getValue() < reportValidityMs) {
187	        validReports.add(entry.getKey());
188	      }
189	    }
190	    return validReports;
191	  }
192	
193	  /**
194	   * Retrieve all valid reports as a JSON string.
195	   * @return serialized representation of valid reports. null if
196	   *         serialization failed.
197	   */
198	  public String getJson() {
199	    Collection<ReportForJson> validReports = getJsonReports(
200	        maxNodesToReport);
201	    try {
202	      return WRITER.writeValueAsString(validReports);
203	    } catch (JsonProcessingException e) {
204	      // Failed to serialize. Don't log the exception call stack.
205	      LOG.debug("Failed to serialize statistics" + e);
206	      return null;
207	    }
208	  }
209	
210	  /**
211	   * This structure is a thin wrapper over reports to make Json
212	   * [de]serialization easy.
213	   */
214	  public static class ReportForJson {
215	    @JsonProperty("SlowNode")
216	    final private String slowNode;
217	
218	    @JsonProperty("ReportingNodes")
219	    final private SortedSet<String> reportingNodes;
220	
221	    public ReportForJson(
222	        @JsonProperty("SlowNode") String slowNode,
223	        @JsonProperty("ReportingNodes") SortedSet<String> reportingNodes) {
224	      this.slowNode = slowNode;
225	      this.reportingNodes = reportingNodes;
226	    }
227	
228	    public String getSlowNode() {
229	      return slowNode;
230	    }
231	
232	    public SortedSet<String> getReportingNodes() {
233	      return reportingNodes;
234	    }
235	  }
236	
237	  /**
238	   * Returns all tracking slow peers.
239	   * @param numNodes
240	   * @return
241	   */
242	  public ArrayList<String> getSlowNodes(int numNodes) {
243	    Collection<ReportForJson> jsonReports = getJsonReports(numNodes);
244	    ArrayList<String> slowNodes = new ArrayList<>();
245	    for (ReportForJson jsonReport : jsonReports) {
246	      slowNodes.add(jsonReport.getSlowNode());
247	    }
248	    if (!slowNodes.isEmpty()) {
249	      LOG.warn("Slow nodes list: " + slowNodes);
250	    }
251	    return slowNodes;
252	  }
253	
254	  /**
255	   * Retrieve reports in a structure for generating JSON, limiting the
256	   * output to the top numNodes nodes i.e nodes with the most reports.
257	   * @param numNodes number of nodes to return. This is to limit the
258	   *                 size of the generated JSON.
259	   */
260	  private Collection<ReportForJson> getJsonReports(int numNodes) {
261	    if (allReports.isEmpty()) {
262	      return Collections.emptyList();
263	    }
264	
265	    final PriorityQueue<ReportForJson> topNReports =
266	        new PriorityQueue<>(allReports.size(),
267	            new Comparator<ReportForJson>() {
268	          @Override
269	          public int compare(ReportForJson o1, ReportForJson o2) {
270	            return Ints.compare(o1.reportingNodes.size(),
271	                o2.reportingNodes.size());
272	          }
273	        });
274	
275	    final long now = timer.monotonicNow();
276	
277	    for (Map.Entry<String, ConcurrentMap<String, Long>> entry :
278	        allReports.entrySet()) {
279	      SortedSet<String> validReports = filterNodeReports(
280	          entry.getValue(), now);
281	      if (!validReports.isEmpty()) {
282	        if (topNReports.size() < numNodes) {
283	          topNReports.add(new ReportForJson(entry.getKey(), validReports));
284	        } else if (topNReports.peek().getReportingNodes().size() <
285	            validReports.size()){
286	          // Remove the lowest element
287	          topNReports.poll();
288	          topNReports.add(new ReportForJson(entry.getKey(), validReports));
289	        }
290	      }
291	    }
292	    return topNReports;
293	  }
294	
295	  @VisibleForTesting
296	  long getReportValidityMs() {
297	    return reportValidityMs;
298	  }
299	}

