    try {
      if (newVal == null) {
        // set to default
        datanodeManager.setHeartbeatRecheckInterval(
            DFS_NAMENODE_HEARTBEAT_RECHECK_INTERVAL_DEFAULT);
        return String.valueOf(DFS_NAMENODE_HEARTBEAT_RECHECK_INTERVAL_DEFAULT);
      } else {
        datanodeManager.setHeartbeatRecheckInterval(Integer.parseInt(newVal));
        return String.valueOf(datanodeManager.getHeartbeatRecheckInterval());
      }
    } catch (NumberFormatException nfe) {
      throw new ReconfigurationException(property, newVal, getConf().get(
          property), nfe);
    } finally {
      namesystem.writeUnlock();
      LOG.info("RECONFIGURE* changed heartbeatRecheckInterval to "
          + datanodeManager.getHeartbeatRecheckInterval());
    }
  }

  private String reconfigureBlockInvalidateLimit(
      final DatanodeManager datanodeManager, final String newVal)
      throws ReconfigurationException {
    namesystem.writeLock();
    try {
      if (newVal == null) {
        // set to default
        int defaultBlockInvalidateLimit = Math.max(
            20 * (int) (datanodeManager.getHeartbeatInterval()),
            DFS_BLOCK_INVALIDATE_LIMIT_DEFAULT);
        datanodeManager.setBlockInvalidateLimit(defaultBlockInvalidateLimit);
        return String.valueOf(defaultBlockInvalidateLimit);
      }

      int blockInvalidateLimit;
      try {
        blockInvalidateLimit = Integer.parseInt(newVal);
      } catch (NumberFormatException nfe) {
        throw new ReconfigurationException(DFS_BLOCK_INVALIDATE_LIMIT_KEY,
            newVal, getConf().get(DFS_BLOCK_INVALIDATE_LIMIT_KEY), nfe);
      }
      if (blockInvalidateLimit <= 0) {
        throw new ReconfigurationException(DFS_BLOCK_INVALIDATE_LIMIT_KEY,
            newVal, getConf().get(DFS_BLOCK_INVALIDATE_LIMIT_KEY));
      }

      int effectedLimit = Math.max(
          20 * (int) (datanodeManager.getHeartbeatInterval()),
          blockInvalidateLimit);
      datanodeManager.setBlockInvalidateLimit(effectedLimit);
      return String.valueOf(effectedLimit);
    } finally {
      namesystem.writeUnlock();
      LOG.info("RECONFIGURE* changed blockInvalidateLimit to "
          + datanodeManager.getBlockInvalidateLimit());
    }
  }

